def prepare(root):
    root=Path(root)
    root.mkdir(parents=True,exist_ok=False)
    result=[]
    for name,source in sorted(STUBS.items()):
        path=root/name;path.parent.mkdir(parents=True,exist_ok=True)
        with path.open('x',encoding='utf-8') as stream:stream.write(source+'\n')
        result.append(path)
    return result
